(function () {
  const D = window.DEMO_DOCS;
  // O que foi digitado na tela de notas do protótipo fica guardado neste navegador e aparece no histórico impresso
  const histSalvo = (id) => { try { return JSON.parse(localStorage.getItem('iel2-hist-' + id) || 'null'); } catch { return null; } };
  D.historicoDe = (id) => { const h = D.historico[id]; if (!h) return null; const s = histSalvo(id); return s ? { ...h, anos: s } : h; };
  D.salvarHistorico = (id, anos) => { try { localStorage.setItem('iel2-hist-' + id, JSON.stringify(anos)); } catch { /* sem armazenamento */ } };

  // Parcelas de exemplo para a declaração de pagamento (o app de verdade lê o Excel do ACADESC)
  const parcelas = (mat) => { const ano = new Date().getFullYear() - 1, v = 1230 + (Number(mat) % 7) * 35;
    return Array.from({ length: 12 }, (_, i) => { const m = String(i + 1).padStart(2, '0');
      return { descricao: `Mensalidade ${m}/${ano}`, venc: `${ano}-${m}-10`, pagto: `${ano}-${m}-0${(i % 8) + 1}`, valor: v, juros: 0, desconto: 0, recebido: v }; }); };

  const responder = (corpo) => Promise.resolve(new Response(JSON.stringify(corpo), { status: 200, headers: { 'Content-Type': 'application/json' } }));
  const naoTem = (msg) => Promise.resolve(new Response(JSON.stringify({ erro: msg }), { status: 404, headers: { 'Content-Type': 'application/json' } }));
  const original = window.fetch && window.fetch.bind(window);
  window.fetch = function (url, op) {
    const u = new URL(String(url), 'http://prototipo.local/');
    if (!u.pathname.startsWith('/api/')) return original ? original(url, op) : naoTem('sem rede');
    const p = u.pathname;
    if (p === '/api/documentos/alunos') {
      const ids = (u.searchParams.get('ids') || '').split(',').filter(Boolean);
      const r = ids.map((id) => D.alunos[id]).filter(Boolean);
      if (!r.length) return naoTem('Aluno não encontrado na demonstração');
      return responder({ ...r[0], alunos: r.flatMap((x) => x.alunos) });
    }
    let m = /^\/api\/historico\/aluno\/(\d+)$/.exec(p);
    if (m) { const h = D.historicoDe(m[1]); return h ? responder(h) : naoTem('Sem histórico na demonstração'); }
    if (p === '/api/relatorios') return responder(D.relatorios);
    if (p === '/api/documentos/ler-pagamentos') return responder({ linhas: parcelas(u.searchParams.get('mat')) });
    if (p === '/api/emissoes') return responder({ ok: true });
    return naoTem('Este documento não está no protótipo');
  };
})();
